import { describe, expect, it } from 'vitest';
import { makeSecondSalary } from '../../test/fixtures';
import { describeSecondSalary, SECOND_SALARY_EXPLANATION } from '../describeSecondSalary';

const describeIt = (overrides = {}) => describeSecondSalary(makeSecondSalary(overrides), 'en-US');

describe('describeSecondSalary', () => {
  it('explains what a second salary is in one plain sentence', () => {
    expect(SECOND_SALARY_EXPLANATION).toBe(
      'Passive monthly income generated by your invested portfolio—acting as an independent paycheck that covers your life without working.'
    );
    expect(describeIt().explanation).toBe(SECOND_SALARY_EXPLANATION);
  });

  it('shows what the portfolio pays each month', () => {
    expect(describeIt().income).toBe('€1,000 / month');
    expect(describeIt({ secondSalaryMinor: 123_456 }).income).toBe('€1,234.56 / month');
    expect(describeIt({ secondSalaryMinor: 0 }).income).toBe('€0 / month');
  });

  it('has no bar until the person sets a target', () => {
    expect(describeIt({ target: null }).target).toBeNull();
  });

  it('draws one bar toward the target the person chose', () => {
    expect(describeIt().target).toEqual({
      label: '€2,500 / month',
      fill: 0.4,
      summary: '€1,000 / month of your €2,500 / month target',
      reached: false,
      note: 'Needs €500,000 invested to get there.',
    });
  });

  it('says so when the target is reached', () => {
    const { target } = describeIt({ target: { monthlyMinor: 250_000, progress: 1, reached: true, capitalNeededMinor: 50_000_000 } });
    expect(target).toMatchObject({ fill: 1, reached: true, note: 'Target reached.' });
  });

  it.each([
    [1, 'Covers 100% of your utilities & subscriptions.'],
    [2, 'Covers 100% of your rent.'],
    [3, '100% Living Cost Autonomy (Your capital covers your monthly living costs).'],
  ] as const)('says what living costs it already covers (milestone %i)', (reachedMilestone, covers) => {
    expect(describeIt({ reachedMilestone }).covers).toBe(covers);
  });

  it('says how far the nearest cost is when none is covered', () => {
    const milestones = makeSecondSalary().milestones.map((milestone) => ({ ...milestone, reached: false, progress: milestone.id === 1 ? 0.456 : 0.1 }));
    expect(describeIt({ reachedMilestone: null, milestones }).covers).toBe('45% of the way to covering your utilities & subscriptions.');
  });

  it('encourages the first step instead of showing 0%', () => {
    const milestones = makeSecondSalary().milestones.map((milestone) => ({ ...milestone, reached: false, progress: 0 }));
    expect(describeIt({ reachedMilestone: null, milestones }).covers).toBe('Every euro invested moves you toward covering your utilities & subscriptions.');
  });

  it('never rounds an unreached cost up to 100%', () => {
    const milestones = makeSecondSalary().milestones.map((milestone) => ({ ...milestone, reached: false, progress: 0.9996 }));
    expect(describeIt({ reachedMilestone: null, milestones }).covers).toMatch(/^99% /);
  });

  it.each([
    ['NO_CURRENT_PHASE', 'Add the place you live now to see what your second salary covers.'],
    ['NO_COSTS', 'Add your monthly costs to see what your second salary covers.'],
    ['CURRENCY_MISMATCH', 'Your costs are in another currency than your portfolio, so they cannot be compared yet.'],
  ] as const)('explains the gap %s instead of guessing', (gap, covers) => {
    expect(describeIt({ gap, milestones: [], reachedMilestone: null }).covers).toBe(covers);
  });
});
